import os
import re
from collections import defaultdict

TICKETS_DIR = "/workspace/tickets"


def main():
    groups = defaultdict(list)
    for name in sorted(os.listdir(TICKETS_DIR)):
        if not name.endswith(".txt") or name.lower().startswith("readme"):
            continue
        match = re.search(r"TICKET-(\d+)", name)
        if match:
            groups[match.group(1)].append(name)

    for ticket_id, names in groups.items():
        if len(names) == 1:
            old_name = names[0]
            new_name = f"TICKET-{ticket_id}.txt"
            os.rename(
                os.path.join(TICKETS_DIR, old_name),
                os.path.join(TICKETS_DIR, new_name),
            )
            print(f"Renamed {old_name} -> {new_name}")
        else:
            # Same numeric ID reused across different years refers to
            # different tickets; keep the year prefix so each record
            # stays distinct instead of one overwriting the other.
            for old_name in names:
                year_match = re.match(r"(\d{4})-", old_name)
                year = year_match.group(1) if year_match else "unknown"
                new_name = f"TICKET-{year}-{ticket_id}.txt"
                os.rename(
                    os.path.join(TICKETS_DIR, old_name),
                    os.path.join(TICKETS_DIR, new_name),
                )
                print(f"Renamed {old_name} -> {new_name}")


if __name__ == "__main__":
    main()

